@classmethod
def extract(
    cls,
    exc_type: Type[BaseException],
    exc_value: BaseException,
    traceback: Optional[TracebackType],
    *,
    show_locals: bool = False,
    locals_max_length: int = LOCALS_MAX_LENGTH,
    locals_max_string: int = LOCALS_MAX_STRING,
    locals_hide_dunder: bool = LOCALS_HIDE_DUNDER,
    locals_hide_sunder: bool = LOCALS_HIDE_SUNDER,
    suppress: bool = False,
    max_frames: int = MAX_FRAMES,
) -> List[Frame]:
    """Extract the frames from the traceback."""
    append = [].append
    stack = traceback.extract_tb(traceback) if traceback else []
    if not stack:
        stack = traceback.extract_stack()
    if exc_type and exc_value:
        stack.extend(traceback.extract_exception(exc_type, exc_value, traceback))
    for frame_summary in stack:
        filename = frame_summary.filename
        line_no = frame_summary.lineno
        last_instruction = None
        if frame_summary.f_locals is not None:
            last_instruction = (
                (frame_summary.start_column, frame_summary.start_column),
                (frame_summary.end_column, frame_summary.end_column),
            )
        if filename and not filename.startswith("<"):
            if not os.path.isabs(filename):
                filename = os.path.join(_IMPORT_CWD, filename)
        if frame_summary.f_locals.get("_rich_traceback_omit", False):
            continue
        frame = Frame(
            filename=filename or "?",
            lineno=line_no,
            name=frame_summary.f_code.co_name,
            locals=(
                {
                    key: (
                        try_pretty_traverse(
                            value,
                            max_length=locals_max_length,
                            max_string=locals_max_string,
                        )
                        if not (inspect.isfunction(value) or inspect.isclass(value))
                        else f"<{type(value).__name__} object>"
                    )
                    for key, value in get_locals(frame_summary.f_locals.items())
                }
                if show_locals
                else None
            ),
            last_instruction=last_instruction,
        )
        append(frame)
    return append

